CREATE OR ALTER PROCEDURE dbo.SP_CERRAR_EVALUACION  (        @EvaluacionId INT      , @Usuario      VARCHAR(100)  )  AS  BEGIN        SET NOCOUNT ON;      SET XACT_ABORT ON;          DECLARE            @LoteId                       INT          , @VersionId                    INT          , @VersionFaseId                INT          , @EvaluacionPadreId            INT            , @VersionFaseOrden             INT          , @CodigoReferencia             VARCHAR(30)          , @EsFinal                      BIT            , @SiguienteVersionFaseId       INT          , @SiguienteVersionFaseOrden    INT          , @SiguienteCodigoReferencia    VARCHAR(30)            , @EstadoEvaluacionActualId     INT          , @EstadoLoteActualId           INT            , @EstadoEvalPendienteId        INT          , @EstadoEvalEnProcesoId        INT          , @EstadoEvalTerminadaId        INT          , @EstadoEvalAnuladaId          INT            , @EstadoLoteEvaluacionId       INT          , @EstadoLoteLiberadoId         INT            , @TotalParametros              INT          , @TotalObligatorios            INT          , @ObligatoriosEvaluados        INT          , @Cumplen                      INT          , @NoCumplen                    INT            , @ResultadoGeneral             BIT            , @NuevoEstadoLoteId            INT          , @NuevoEstadoLoteCodigo        VARCHAR(50)            , @EsEvaluacionPorEtapa         BIT = 0          , @EsReevaluacion               BIT = 0;          BEGIN TRY              /* =========================================================             1. ESTADOS DE EVALUACION             ========================================================= */            SELECT              @EstadoEvalPendienteId = EstadoEvaluacionId          FROM dbo.ESTADO_EVALUACION          WHERE Codigo = 'PENDIENTE';              SELECT              @EstadoEvalEnProcesoId = EstadoEvaluacionId          FROM dbo.ESTADO_EVALUACION          WHERE Codigo = 'EN_PROCESO';              SELECT              @EstadoEvalTerminadaId = EstadoEvaluacionId          FROM dbo.ESTADO_EVALUACION          WHERE Codigo = 'TERMINADA';              SELECT              @EstadoEvalAnuladaId = EstadoEvaluacionId          FROM dbo.ESTADO_EVALUACION          WHERE Codigo = 'ANULADA';              IF @EstadoEvalPendienteId IS NULL              RAISERROR(                  'No existe el estado de evaluación PENDIENTE.',                  16,                  1              );              IF @EstadoEvalEnProcesoId IS NULL              RAISERROR(                  'No existe el estado de evaluación EN_PROCESO.',                  16,                  1              );              IF @EstadoEvalTerminadaId IS NULL              RAISERROR(                  'No existe el estado de evaluación TERMINADA.',                  16,                  1              );              IF @EstadoEvalAnuladaId IS NULL              RAISERROR(                  'No existe el estado de evaluación ANULADA.',                  16,                  1              );              /* =========================================================             2. ESTADOS DEL LOTE             ========================================================= */            SELECT              @EstadoLoteEvaluacionId = EstadoLoteId          FROM dbo.ESTADO_LOTE          WHERE Codigo = 'EVALUACION'            AND Estado = 'ACTIVO';              SELECT              @EstadoLoteLiberadoId = EstadoLoteId          FROM dbo.ESTADO_LOTE          WHERE Codigo = 'LIBERADO'            AND Estado = 'ACTIVO';              IF @EstadoLoteEvaluacionId IS NULL              RAISERROR(                  'No existe el estado de lote EVALUACION activo.',                  16,                  1              );              IF @EstadoLoteLiberadoId IS NULL              RAISERROR(                  'No existe el estado de lote LIBERADO activo.',                  16,                  1              );              /* =========================================================             3. INICIAR TRANSACCION             ========================================================= */            BEGIN TRANSACTION;              /* =========================================================             4. BLOQUEAR Y OBTENER EVALUACION             ========================================================= */            SELECT                @EstadoEvaluacionActualId =                      E.EstadoEvaluacionId                , @ResultadoGeneral =                      E.ResultadoGeneral                , @LoteId =                      E.LoteId                , @EstadoLoteActualId =                      L.EstadoLoteId                , @VersionId =                      L.VersionId                , @VersionFaseId =                      E.VersionFaseId                , @EvaluacionPadreId =                      E.EvaluacionPadreId            FROM dbo.EVALUACION E WITH (UPDLOCK, HOLDLOCK)            INNER JOIN dbo.LOTE L WITH (UPDLOCK, HOLDLOCK)              ON L.LoteId = E.LoteId            WHERE E.EvaluacionId = @EvaluacionId            AND E.Estado = 'ACTIVO'            AND L.Estado = 'ACTIVO';              IF @EstadoEvaluacionActualId IS NULL          BEGIN                ROLLBACK TRANSACTION;                SELECT                    1 AS CodigoResultado                  , 'La evaluación no existe o se encuentra inactiva.'                      AS Mensaje;                RETURN;            END;              SET @EsReevaluacion =              CASE                  WHEN @EvaluacionPadreId IS NOT NULL                      THEN 1                  ELSE 0              END;              /* =========================================================             5. VALIDAR ESTADO ACTUAL             ========================================================= */            IF @EstadoEvaluacionActualId = @EstadoEvalPendienteId          BEGIN                ROLLBACK TRANSACTION;                SELECT                    2 AS CodigoResultado                  , 'La evaluación aún se encuentra PENDIENTE. Debe iniciarse antes de cerrarla.'                      AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId;                RETURN;            END;              IF @EstadoEvaluacionActualId = @EstadoEvalTerminadaId          BEGIN                ROLLBACK TRANSACTION;                SELECT                    3 AS CodigoResultado                  , 'La evaluación ya fue cerrada.'                      AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId                  , @EstadoEvalTerminadaId AS EstadoEvaluacionId                  , 'TERMINADA' AS EstadoEvaluacion                  , @ResultadoGeneral AS ResultadoGeneral                    , CASE                        WHEN @ResultadoGeneral = 1                            THEN 'CONFORME'                        WHEN @ResultadoGeneral = 0                            THEN 'NO CONFORME'                        ELSE 'SIN RESULTADO'                    END AS ResultadoDescripcion;                RETURN;            END;              IF @EstadoEvaluacionActualId = @EstadoEvalAnuladaId          BEGIN                ROLLBACK TRANSACTION;                SELECT                    4 AS CodigoResultado                  , 'La evaluación se encuentra ANULADA.'                      AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId;                RETURN;            END;              IF @EstadoEvaluacionActualId <> @EstadoEvalEnProcesoId          BEGIN                ROLLBACK TRANSACTION;                SELECT                    5 AS CodigoResultado                  , 'La evaluación no puede cerrarse en su estado actual.'                      AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId;                RETURN;            END;              /* =========================================================             6. RESOLVER ETAPA ACTUAL             ========================================================= */            IF @VersionFaseId IS NOT NULL          BEGIN                SET @EsEvaluacionPorEtapa = 1;                  SELECT                    @VersionFaseOrden =                          VF.Orden                    , @CodigoReferencia =                          VF.CodigoReferencia                    , @EsFinal =                          VF.EsFinal                FROM dbo.VERSIONFASE VF                WHERE VF.VersionFaseId = @VersionFaseId                AND VF.VersionId = @VersionId                AND VF.Estado = 1;                  IF @VersionFaseOrden IS NULL              BEGIN                    RAISERROR(                      'La etapa asociada a la evaluación no existe o no pertenece a la versión del lote.',                      16,                      1                  );                END;                  /* =====================================================                 SIGUIENTE ETAPA ACTIVA                 ===================================================== */                SELECT TOP (1)                    @SiguienteVersionFaseId =                        VF.VersionFaseId                    , @SiguienteVersionFaseOrden =                        VF.Orden                    , @SiguienteCodigoReferencia =                        VF.CodigoReferencia                FROM dbo.VERSIONFASE VF                WHERE VF.VersionId = @VersionId                AND VF.Estado = 1                AND VF.Orden > @VersionFaseOrden                ORDER BY                    VF.Orden                  , VF.VersionFaseId;            END;              /* =========================================================             7. VALIDAR PADRE DE REEVALUACION               Debe:             - pertenecer al mismo lote             - pertenecer a la misma etapa             - estar TERMINADA             - haber resultado NO CONFORME             ========================================================= */            IF @EvaluacionPadreId IS NOT NULL          BEGIN                IF NOT EXISTS              (                  SELECT 1                    FROM dbo.EVALUACION EP                    WHERE EP.EvaluacionId =                        @EvaluacionPadreId                      AND EP.LoteId =                        @LoteId                      AND EP.Estado =                        'ACTIVO'                      AND EP.EstadoEvaluacionId =                        @EstadoEvalTerminadaId                      AND EP.ResultadoGeneral = 0                      AND                    (                        (                            @VersionFaseId IS NULL                            AND EP.VersionFaseId IS NULL                        )                          OR EP.VersionFaseId =                           @VersionFaseId                    )              )              BEGIN                    RAISERROR(                      'La evaluación padre no es válida para cerrar esta reevaluación.',                      16,                      1                  );                END;            END;              /* =========================================================             8. VALIDAR PARAMETROS OBLIGATORIOS SIN RESULTADO               NORMAL:             todas las características obligatorias de la etapa.               REEVALUACION:             solamente las características que quedaron Cumple = 0             en el padre inmediato.             ========================================================= */            IF EXISTS          (              SELECT 1                FROM dbo.VERSIONCARACTERISTICA VC                LEFT JOIN dbo.EVALUACION_RESULTADO ER                  ON ER.EvaluacionId = @EvaluacionId                 AND ER.VersCaractId = VC.VersCaractId                 AND ER.Estado = 'ACTIVO'                LEFT JOIN dbo.EVALUACION_RESULTADO ERP                  ON ERP.EvaluacionId = @EvaluacionPadreId                 AND ERP.VersCaractId = VC.VersCaractId                 AND ERP.Estado = 'ACTIVO'                WHERE VC.VersionId = @VersionId                AND VC.Estado = 1                AND VC.EsObligatorio = 1                  AND                (                    @VersionFaseId IS NULL                    OR VC.VersionFaseId = @VersionFaseId                )                  AND                (                    @EvaluacionPadreId IS NULL                    OR ERP.Cumple = 0                )                  AND ER.EvaluacionResultadoId IS NULL          )          BEGIN                ROLLBACK TRANSACTION;                SELECT                    6 AS CodigoResultado                  , CASE                        WHEN @EvaluacionPadreId IS NOT NULL                            THEN 'Existen parámetros obligatorios pendientes en la reevaluación.'                        ELSE 'Existen parámetros obligatorios sin registrar.'                    END AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId                  , @VersionFaseId AS VersionFaseId                  , @CodigoReferencia AS CodigoReferencia                  , @EvaluacionPadreId AS EvaluacionPadreId;                RETURN;            END;              /* =========================================================             9. MOTOR DE EVALUACION               1  MINIMO       >=             2  MAXIMO       <=             3  RANGO             4  AUSENCIA             5  CUALITATIVO             9  MAYOR_QUE    >             10 MENOR_QUE    <             11 IGUAL        =             ========================================================= */            UPDATE ER            SET              Cumple =                    CASE VC.TipoCriterioId                        WHEN 1 THEN                          CASE                              WHEN ER.ResultadoNumerico IS NOT NULL                               AND VC.ValorCuantitativoInicial IS NOT NULL                               AND ER.ResultadoNumerico                                      >= VC.ValorCuantitativoInicial                                  THEN 1                              ELSE 0                          END                          WHEN 2 THEN                          CASE                              WHEN ER.ResultadoNumerico IS NOT NULL                               AND VC.ValorCuantitativoFinal IS NOT NULL                               AND ER.ResultadoNumerico                                      <= VC.ValorCuantitativoFinal                                  THEN 1                              ELSE 0                          END                          WHEN 3 THEN                          CASE                              WHEN ER.ResultadoNumerico IS NOT NULL                               AND VC.ValorCuantitativoInicial IS NOT NULL                               AND VC.ValorCuantitativoFinal IS NOT NULL                               AND ER.ResultadoNumerico                                      BETWEEN VC.ValorCuantitativoInicial                                          AND VC.ValorCuantitativoFinal                                  THEN 1                              ELSE 0                          END                          WHEN 4 THEN                          CASE                              WHEN                                  UPPER                                  (                                      LTRIM                                      (                                          RTRIM                                          (                                              ISNULL(                                                  ER.ResultadoTexto,                                                  ''                                              )                                          )                                      )                                  )                                  =                                  UPPER                                  (                                      LTRIM                                      (                                          RTRIM                                          (                                              ISNULL(                                                  VC.ValorCualitativo,                                                  ''                                              )                                          )                                      )                                  )                                  THEN 1                              ELSE 0                          END                          /* CUALITATIVO:                         conservar decisión del evaluador */                        WHEN 5 THEN                          ER.Cumple                          WHEN 9 THEN                          CASE                              WHEN ER.ResultadoNumerico IS NOT NULL                               AND VC.ValorCuantitativoInicial IS NOT NULL                               AND ER.ResultadoNumerico                                      > VC.ValorCuantitativoInicial                                  THEN 1                              ELSE 0                          END                          WHEN 10 THEN                          CASE                              WHEN ER.ResultadoNumerico IS NOT NULL                               AND VC.ValorCuantitativoFinal IS NOT NULL                               AND ER.ResultadoNumerico                                      < VC.ValorCuantitativoFinal                                  THEN 1                              ELSE 0                          END                          WHEN 11 THEN                          CASE                              WHEN ER.ResultadoNumerico IS NOT NULL                               AND VC.ValorCuantitativoIgual IS NOT NULL                               AND ER.ResultadoNumerico                                      = VC.ValorCuantitativoIgual                                  THEN 1                              ELSE 0                          END                          ELSE NULL                    END                  , AudUsuarioModificacion = @Usuario                , AudFechaActualizacion  = GETDATE()              FROM dbo.EVALUACION_RESULTADO ER            INNER JOIN dbo.VERSIONCARACTERISTICA VC              ON VC.VersCaractId = ER.VersCaractId             AND VC.VersionId = @VersionId            LEFT JOIN dbo.EVALUACION_RESULTADO ERP              ON ERP.EvaluacionId = @EvaluacionPadreId             AND ERP.VersCaractId = VC.VersCaractId             AND ERP.Estado = 'ACTIVO'            WHERE ER.EvaluacionId = @EvaluacionId            AND ER.Estado = 'ACTIVO'            AND VC.Estado = 1              AND            (                @VersionFaseId IS NULL                OR VC.VersionFaseId = @VersionFaseId            )              AND            (                @EvaluacionPadreId IS NULL                OR ERP.Cumple = 0            );              /* =========================================================             10. VALIDAR OBLIGATORIOS INDETERMINADOS             ========================================================= */            IF EXISTS          (              SELECT 1                FROM dbo.VERSIONCARACTERISTICA VC                LEFT JOIN dbo.EVALUACION_RESULTADO ER                  ON ER.EvaluacionId = @EvaluacionId                 AND ER.VersCaractId = VC.VersCaractId                 AND ER.Estado = 'ACTIVO'                LEFT JOIN dbo.EVALUACION_RESULTADO ERP                  ON ERP.EvaluacionId = @EvaluacionPadreId                 AND ERP.VersCaractId = VC.VersCaractId                 AND ERP.Estado = 'ACTIVO'                WHERE VC.VersionId = @VersionId                AND VC.Estado = 1                AND VC.EsObligatorio = 1                  AND                (                    @VersionFaseId IS NULL                    OR VC.VersionFaseId = @VersionFaseId                )                  AND                (                    @EvaluacionPadreId IS NULL                    OR ERP.Cumple = 0                )                  AND                (                    ER.EvaluacionResultadoId IS NULL                    OR ER.Cumple IS NULL                )          )          BEGIN                ROLLBACK TRANSACTION;                SELECT                    7 AS CodigoResultado                  , CASE                        WHEN @EvaluacionPadreId IS NOT NULL                            THEN 'Existen parámetros de la reevaluación que no pudieron ser evaluados.'                        ELSE 'Existen parámetros obligatorios que no pudieron ser evaluados.'                    END AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId                  , @VersionFaseId AS VersionFaseId                  , @CodigoReferencia AS CodigoReferencia                  , @EvaluacionPadreId AS EvaluacionPadreId;                RETURN;            END;              /* =========================================================             11. RESUMEN DEL INTENTO               NORMAL:                 toda la etapa.               REEVALUACION:                 únicamente los parámetros fallidos del padre.             ========================================================= */            SELECT                @TotalParametros =                    COUNT(*)                , @TotalObligatorios =                    SUM                    (                        CASE                            WHEN VC.EsObligatorio = 1                                THEN 1                            ELSE 0                        END                    )                , @ObligatoriosEvaluados =                    SUM                    (                        CASE                            WHEN VC.EsObligatorio = 1                             AND ER.EvaluacionResultadoId IS NOT NULL                                THEN 1                            ELSE 0                        END                    )                , @Cumplen =                    SUM                    (                        CASE                            WHEN VC.EsObligatorio = 1                             AND ER.Cumple = 1                                THEN 1                            ELSE 0                        END                    )                , @NoCumplen =                    SUM                    (                        CASE                            WHEN VC.EsObligatorio = 1                             AND ER.Cumple = 0                                THEN 1                            ELSE 0                        END                    )            FROM dbo.VERSIONCARACTERISTICA VC            LEFT JOIN dbo.EVALUACION_RESULTADO ER              ON ER.EvaluacionId = @EvaluacionId             AND ER.VersCaractId = VC.VersCaractId             AND ER.Estado = 'ACTIVO'            LEFT JOIN dbo.EVALUACION_RESULTADO ERP              ON ERP.EvaluacionId = @EvaluacionPadreId             AND ERP.VersCaractId = VC.VersCaractId             AND ERP.Estado = 'ACTIVO'            WHERE VC.VersionId = @VersionId            AND VC.Estado = 1              AND            (                @VersionFaseId IS NULL                OR VC.VersionFaseId = @VersionFaseId            )              AND            (                @EvaluacionPadreId IS NULL                OR ERP.Cumple = 0            );              SET @TotalParametros =              ISNULL(@TotalParametros, 0);            SET @TotalObligatorios =              ISNULL(@TotalObligatorios, 0);            SET @ObligatoriosEvaluados =              ISNULL(@ObligatoriosEvaluados, 0);            SET @Cumplen =              ISNULL(@Cumplen, 0);            SET @NoCumplen =              ISNULL(@NoCumplen, 0);              /* =========================================================             12. VALIDACIONES DE SEGURIDAD             ========================================================= */            IF @TotalParametros = 0          BEGIN                ROLLBACK TRANSACTION;                SELECT                    8 AS CodigoResultado                  , CASE                        WHEN @EvaluacionPadreId IS NOT NULL                            THEN 'La reevaluación no contiene parámetros pendientes del intento anterior.'                        ELSE 'La etapa no contiene parámetros para evaluar.'                    END AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId                  , @VersionFaseId AS VersionFaseId                  , @EvaluacionPadreId AS EvaluacionPadreId;                RETURN;            END;              IF @TotalObligatorios = 0          BEGIN                ROLLBACK TRANSACTION;                SELECT                    9 AS CodigoResultado                  , 'La evaluación no contiene parámetros obligatorios para evaluar.'                      AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId                  , @VersionFaseId AS VersionFaseId;                RETURN;            END;              IF @ObligatoriosEvaluados <> @TotalObligatorios          BEGIN                ROLLBACK TRANSACTION;                SELECT                    10 AS CodigoResultado                  , CASE                        WHEN @EvaluacionPadreId IS NOT NULL                            THEN 'No se encuentran registrados todos los parámetros obligatorios de la reevaluación.'                        ELSE 'No se encuentran registrados todos los parámetros obligatorios.'                    END AS Mensaje                  , @EvaluacionId AS EvaluacionId                  , @LoteId AS LoteId                  , @VersionFaseId AS VersionFaseId                  , @EvaluacionPadreId AS EvaluacionPadreId                  , @TotalObligatorios AS TotalObligatorios                  , @ObligatoriosEvaluados AS ObligatoriosEvaluados;                RETURN;            END;              /* =========================================================             13. RESULTADO GENERAL DEL INTENTO             ========================================================= */            SET @ResultadoGeneral =              CASE                  WHEN @NoCumplen > 0                      THEN 0                  ELSE 1              END;              /* =========================================================             14. DETERMINAR ESTADO DEL LOTE               REGLA NUEVA:               NO CUMPLE                 -> evaluación TERMINADA / ResultadoGeneral = 0                 -> lote permanece EVALUACION                 -> siguiente etapa bloqueada                 -> se permite crear reevaluación               CUMPLE + ETAPA INTERMEDIA                 -> lote EVALUACION                 -> siguiente etapa habilitada               CUMPLE + ETAPA FINAL                 -> lote LIBERADO               LEGACY conforme                 -> mantiene comportamiento LIBERADO             ========================================================= */            IF @ResultadoGeneral = 0          BEGIN                SET @NuevoEstadoLoteId =                  @EstadoLoteEvaluacionId;                SET @NuevoEstadoLoteCodigo =                  'EVALUACION';            END            ELSE IF @EsEvaluacionPorEtapa = 0          BEGIN                /* LEGACY */                SET @NuevoEstadoLoteId =                  @EstadoLoteLiberadoId;                SET @NuevoEstadoLoteCodigo =                  'LIBERADO';            END            ELSE IF @EsFinal = 1          BEGIN                /* ETAPA FINAL CONFORME */                SET @NuevoEstadoLoteId =                  @EstadoLoteLiberadoId;                SET @NuevoEstadoLoteCodigo =                  'LIBERADO';            END            ELSE IF @SiguienteVersionFaseId IS NOT NULL          BEGIN                /* ETAPA INTERMEDIA CONFORME */                SET @NuevoEstadoLoteId =                  @EstadoLoteEvaluacionId;                SET @NuevoEstadoLoteCodigo =                  'EVALUACION';            END            ELSE          BEGIN                RAISERROR(                  'La etapa actual no está marcada como final y no existe una siguiente etapa activa.',                  16,                  1              );            END;              /* =========================================================             15. CERRAR EVALUACION             ========================================================= */            UPDATE dbo.EVALUACION            SET                EstadoEvaluacionId =                      @EstadoEvalTerminadaId                , ResultadoGeneral =                      @ResultadoGeneral                , FechaFin =                      GETDATE()                , AudUsuarioModificacion =                      @Usuario                , AudFechaActualizacion =                      GETDATE()            WHERE EvaluacionId = @EvaluacionId            AND EstadoEvaluacionId = @EstadoEvalEnProcesoId            AND Estado = 'ACTIVO';              IF @@ROWCOUNT <> 1          BEGIN                RAISERROR(                  'No se pudo cerrar la evaluación.',                  16,                  1              );            END;              /* =========================================================             16. ACTUALIZAR ESTADO DEL LOTE             ========================================================= */            UPDATE dbo.LOTE            SET                EstadoLoteId =                      @NuevoEstadoLoteId                , AudUsuarioModificacion =                      @Usuario                , AudFechaActualizacion =                      GETDATE()            WHERE LoteId = @LoteId            AND Estado = 'ACTIVO';              IF @@ROWCOUNT <> 1          BEGIN                RAISERROR(                  'No se pudo actualizar el estado del lote.',                  16,                  1              );            END;              /* =========================================================             17. CONFIRMAR TRANSACCION             ========================================================= */            COMMIT TRANSACTION;              /* =========================================================             18. RESULTADO             ========================================================= */            SELECT                0 AS CodigoResultado                , CASE                      WHEN @ResultadoGeneral = 0                        THEN                        'Evaluación cerrada. La etapa requiere reevaluación y el lote permanece en EVALUACION.'                      WHEN @EsEvaluacionPorEtapa = 1                     AND @EsFinal = 0                     AND @SiguienteVersionFaseId IS NOT NULL                        THEN                        'Etapa cerrada correctamente. El lote continúa en EVALUACION y puede avanzar a la siguiente etapa.'                      WHEN @ResultadoGeneral = 1                        THEN                        'Evaluación cerrada correctamente. El lote fue LIBERADO.'                      ELSE                        'Evaluación cerrada correctamente.'                  END AS Mensaje                  /* EVALUACION */                , @EvaluacionId                  AS EvaluacionId                , @EstadoEvalTerminadaId                  AS EstadoEvaluacionId                , 'TERMINADA'                  AS EstadoEvaluacion                , @ResultadoGeneral                  AS ResultadoGeneral                , CASE                    WHEN @ResultadoGeneral = 1                        THEN 'CONFORME'                    ELSE 'NO CONFORME'                END AS ResultadoDescripcion                  /* REEVALUACION */                , @EvaluacionPadreId                  AS EvaluacionPadreId                , @EsReevaluacion                  AS EsReevaluacion                , CASE                    WHEN @ResultadoGeneral = 0                        THEN CAST(1 AS BIT)                    ELSE CAST(0 AS BIT)                END AS RequiereReevaluacion                  /* LOTE */                , @LoteId                  AS LoteId                , @NuevoEstadoLoteId                  AS EstadoLoteId                , @NuevoEstadoLoteCodigo                  AS EstadoLote                  /* ETAPA ACTUAL */                , @VersionFaseId                  AS VersionFaseId                , @VersionFaseOrden                  AS VersionFaseOrden                , @CodigoReferencia                  AS CodigoReferencia                , @EsFinal                  AS EsFinal                  /* SIGUIENTE ETAPA */                , @SiguienteVersionFaseId                  AS SiguienteVersionFaseId                , @SiguienteVersionFaseOrden                  AS SiguienteVersionFaseOrden                , @SiguienteCodigoReferencia                  AS SiguienteCodigoReferencia                , CASE                    WHEN @ResultadoGeneral = 1                     AND @EsEvaluacionPorEtapa = 1                     AND @EsFinal = 0                     AND @SiguienteVersionFaseId IS NOT NULL                        THEN CAST(1 AS BIT)                    ELSE CAST(0 AS BIT)                END AS TieneSiguienteEtapa                  /* RESUMEN DEL INTENTO */                , @TotalParametros                  AS TotalParametros                , @TotalObligatorios                  AS TotalObligatorios                , @ObligatoriosEvaluados                  AS ObligatoriosEvaluados                , @Cumplen                  AS Cumplen                , @NoCumplen                  AS NoCumplen;          END TRY        BEGIN CATCH            IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION;              SELECT                -1 AS CodigoResultado              , ERROR_NUMBER() AS ErrorNumero              , ERROR_LINE() AS ErrorLinea              , ERROR_PROCEDURE() AS ErrorProcedimiento              , ERROR_MESSAGE() AS Mensaje;        END CATCH;    END;
GO
